<script setup lang="ts">import{onMounted,ref}from'vue';import{useRoute}from'vue-router';import DefaultLayout from '@/layouts/DefaultLayout.vue';import BaseButton from '@/components/ui/BaseButton.vue';import{useApi}from'@/composables/useApi';import type{ApiResponse,Order}from'@/types';const route=useRoute(),api=useApi(),order=ref<Order|null>(null),error=ref('');async function load(){try{const r=await api.get<ApiResponse<Order>>(`/orders/${route.params.orderId}`);order.value=r.data||null}catch(e){error.value=e instanceof Error?e.message:'Không tải được kết quả'}}onMounted(load)</script>
<template><DefaultLayout><main class="mx-auto max-w-xl px-4 py-16 text-center"><div class="rounded-3xl border bg-white p-9 dark:border-slate-800 dark:bg-slate-900"><div class="text-6xl">{{ order?.status==='PAID'?'✅':order?.status==='CANCELLED'?'❌':'⏳' }}</div><h1 class="mt-5 text-3xl font-extrabold">{{ order?.status==='PAID'?'Thanh toán thành công':order?.status==='CANCELLED'?'Đơn đã hủy':'Đang chờ thanh toán' }}</h1><p v-if="order" class="mt-3 text-slate-500">{{ order.orderNumber }}</p><p v-if="error" class="mt-3 text-red-600">{{ error }}</p><div class="mt-7 flex justify-center gap-3"><BaseButton variant="outline" @click="load">Kiểm tra lại</BaseButton><RouterLink v-if="order?.status==='PAID'" to="/my-courses" class="rounded-xl bg-purple-600 px-5 py-3 font-bold text-white">Học ngay</RouterLink><RouterLink v-else-if="order" :to="`/checkout/${order.id}`" class="rounded-xl bg-purple-600 px-5 py-3 font-bold text-white">Thanh toán</RouterLink></div></div></main></DefaultLayout></template>
